questions.safe_code:
1  // 권한은 서버 세션/DB의 사용자 정보로 판정 (쿠키 role 값에 의존하지 않음)
2  public boolean isAdmin(HttpServletRequest req) {
3    HttpSession session = req.getSession(false);
4    if (session == null) return false;          // NULL 검사
5    Long userId = (Long) session.getAttribute("userId");
6    if (userId == null) return false;           // NULL 검사
7    Role role = userRepository.findRoleByUserId(userId); // 서버 DB에서 역할 조회
8    return role == Role.ADMIN;
9  }

